//! Robust spectral summaries of raw samples; no frequency notches applied.
use anyhow::Result;use rustplotlib::*;use serde_json::Value;use std::path::Path;fn med(mut v:Vec<f64>)->f64{v.sort_by(f64::total_cmp);v[v.len()/2]}
fn main()->Result<()>{let a:Vec<_>=std::env::args().collect();let f=hdf5::File::open(&a[1])?;let d:Value=serde_json::from_slice(&f.dataset("json_utf8")?.read_raw::<u8>()?)?;let rows=d["rows"].as_array().unwrap();let out=Path::new(&a[2]);std::fs::create_dir_all(out)?;let mut psq=vec![vec![];256];let mut psf=vec![vec![];1024];let mut excess=vec![0f64;256];for row in rows{let q:Vec<_>=row["quiet_psd"].as_array().unwrap().iter().map(|v|v.as_f64().unwrap()).collect();let norm=q.iter().sum::<f64>()/256.;for k in 0..256{psq[k].push(10.*(q[k]/norm).log10());let bg=med((-8i32..=8).filter(|j|j.abs()>2).map(|j|q[(k as i32+j).rem_euclid(256)as usize]).collect());excess[k]=excess[k].max(10.*(q[k]/bg).log10());}for k in 0..1024{psf[k].push(10.*(row["full_psd"][k].as_f64().unwrap()/norm).log10());}}
let fq:Vec<_>=d["quiet_frequency_hz"].as_array().unwrap().iter().map(|v|v.as_f64().unwrap()/1000.).collect();let ff:Vec<_>=d["full_frequency_hz"].as_array().unwrap().iter().map(|v|v.as_f64().unwrap()/1000.).collect();let q:Vec<_>=psq.into_iter().map(med).collect();let p:Vec<_>=psf.into_iter().map(med).collect();let lo=q.iter().chain(&p).copied().fold(f64::INFINITY,f64::min).floor()-1.;let hi=q.iter().chain(&p).copied().fold(f64::NEG_INFINITY,f64::max).ceil()+1.;let mut fig=Figure::new(IntendedUse::ArticleWide);fig.width_mm=180.;fig.height_mm=137.;fig.latex.cache=out.join("latex-cache");let mut ax=Axes::new([-50.,50.],[lo,hi],"","PSD / quiet mean (dB)");ax.xticks=vec![-50.,-25.,0.,25.,50.];ax.show_x_axis=false;let mut top=Panel::new(Rect::new(23.,16.,140.,38.),ax);top.plot(ff.iter().copied().zip(p).map(|(x,y)|[x,y]).collect(),"Signal-window median");top.plot(fq.iter().copied().zip(q).map(|(x,y)|[x,y]).collect(),"Quiet-tail median");fig.panels.push(top);let mut ax=Axes::new([-50.,50.],[0.,8.],"Complex baseband offset (kHz)","Max local quiet excess (dB)");ax.xticks=vec![-50.,-25.,0.,25.,50.];ax.yticks=vec![0.,2.,4.,6.,8.];let mut bottom=Panel::new(Rect::new(23.,72.,140.,38.),ax);bottom.push(Layer::Line(Line::new(fq.iter().copied().zip(excess).map(|(x,y)|[x,y]).collect(),"black")));fig.panels.push(bottom);fig.labels.push(Label::new("SYISR AC: raw complex-baseband spectral check",90.,5.));fig.labels.push(Label::new(format!("{} beam/hour samples; 128 contiguous pulses each; 11 beams",rows.len()),90.,128.));fig.save(out.join("raw-band-spectrum.png"))?;Ok(())}
